elastic-esql.query:
from * metadata _id, _index, _version | where unified_log.subsystem=="com.apple.network" and (message like "*DNS query failed*" or message like "*resolution error*" or message like "*NXDOMAIN*")
| eval timebucket=date_trunc(1minutes, @timestamp) | stats event_count=count() by timebucket, host.name
| where event_count > 50

from * metadata _id, _index, _version | where event.action=="signal" and (signal.number in (9, 15))
| eval timebucket=date_trunc(1minutes, @timestamp) | stats event_count=count() by timebucket, host.name, process.pid
| where event_count > 10
